insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_1_v1'
from (values
('127.2.d.1.A',2,'After taking a career interest inventory, a student should:','["review the results and discuss what they suggest", "decide nothing and tell no one", "ignore every career listed", "throw away the results"]'::jsonb,0,'Assessment results are a starting point for planning.','original'),
('127.2.d.1.A',2,'A student compares assessment results with her own interests. This is:','["scheduling a shift", "analyzing assessment results", "filing taxes", "copying a resume"]'::jsonb,1,'Analysis connects results to goals.','original'),
('127.2.d.1.B',1,'The CTE career clusters are:','["school bus routes", "a list of college mascots", "groups of related occupations and industries", "types of tax forms"]'::jsonb,2,'Clusters organize careers by related fields.','original'),
('127.2.d.1.B',1,'Which of these is a career cluster?','["Spring Break", "Hall Pass", "Lunch Period", "Health Science"]'::jsonb,3,'Health Science is a CTE cluster.','original'),
('127.2.d.1.C',2,'Within the Architecture and Construction cluster, a student could identify a career as an:','["electrician", "court reporter", "pastry chef", "pediatric nurse"]'::jsonb,0,'Electricians work in construction.','original'),
('127.2.d.1.C',2,'Exploring several jobs within one cluster helps a student to:','["avoid planning", "see the variety of opportunities available", "limit choices to one", "skip research"]'::jsonb,1,'Clusters contain many related careers.','original'),
('127.2.d.1.D',3,'An emerging occupation is one that:','["pays no wages", "has existed unchanged for centuries", "is new or growing because of changes in technology or society", "has been eliminated"]'::jsonb,2,'Emerging occupations appear as industries change.','original'),
('127.2.d.1.D',3,'Which resource helps a student research emerging occupations?','["a game show", "a restaurant menu", "a bus schedule", "labor market projections from a government agency"]'::jsonb,3,'Projections show where jobs are growing.','original'),
('127.2.d.2.A',2,'To learn what a career requires, a student should research:','["education, training and certification needs", "only the company logo", "only the office color", "only the commute music"]'::jsonb,0,'Requirements guide planning.','original'),
('127.2.d.2.A',2,'A license required to work in a field is an example of:','["a hobby", "a credential requirement", "a vacation", "a rumor"]'::jsonb,1,'Credentials show a worker meets standards.','original'),
('127.2.d.2.B',2,'Which resource helps a student compare training programs?','["a weather report", "a sports page", "college and technical school websites", "a movie review"]'::jsonb,2,'School websites list programs and costs.','original'),
('127.2.d.2.B',2,'A school counselor can help a student:','["skip all classes", "forget personal goals", "avoid every choice", "evaluate education and training options"]'::jsonb,3,'Counselors advise on options.','original'),
('127.2.d.3.A',2,'To move from middle school to high school, a student needs to know:','["course and credit requirements", "only locker colors", "only bus numbers", "only lunch menus"]'::jsonb,0,'Academic requirements guide the transition.','original'),
('127.2.d.3.A',2,'A graduation plan lists:','["school mascot history", "the courses a student will take to meet requirements", "every friend''s name", "weekly cafeteria prices"]'::jsonb,1,'It maps the path to graduation.','original'),
('127.2.d.3.B',2,'Which can earn college credit while a student is in high school?','["lunch period", "a pep rally", "Advanced Placement exams", "study hall"]'::jsonb,2,'AP exams can earn college credit.','original'),
('127.2.d.3.B',2,'Dual credit courses let students:','["skip graduation", "avoid exams", "get paid by the school", "earn high school and college credit at the same time"]'::jsonb,3,'One course counts for both levels.','original'),
('127.2.d.3.C',2,'Which can help pay for college?','["scholarships and grants", "parking tickets", "detention slips", "late fees"]'::jsonb,0,'Scholarships and grants reduce costs.','original'),
('127.2.d.3.C',2,'The FAFSA is used to apply for:','["a passport", "federal student financial aid", "a library card", "a driver license"]'::jsonb,1,'The FAFSA starts the aid process.','original'),
('127.2.d.3.D',2,'Effective college and career planning can:','["decide for other people", "guarantee no obstacles", "help a student make informed choices and reach goals", "remove the need to work"]'::jsonb,2,'Planning improves decisions.','original'),
('127.2.d.3.D',2,'Which shows the benefit of planning early?','["A student ignores deadlines", "A student waits until after graduation", "A student never asks questions", "A student chooses courses that match a career pathway"]'::jsonb,3,'Early planning aligns courses with goals.','original'),
('127.2.d.3.E',3,'Scores on tests such as the SAT or ACT can affect:','["college admission and scholarship options", "locker numbers", "bus assignments", "lunch choices"]'::jsonb,0,'Scores are used in admissions and aid.','original'),
('127.2.d.3.E',3,'The ASVAB is commonly used to:','["book a flight", "show aptitudes for military career fields", "renew a license", "pay college tuition"]'::jsonb,1,'It measures strengths for military jobs.','original'),
('127.2.d.3.F',2,'Joining a school club or volunteer program can help a student:','["skip classes", "lose interests", "build skills, leadership and experience for future goals", "avoid learning"]'::jsonb,2,'Activities build experience.','original'),
('127.2.d.3.F',2,'Co-curricular and extracurricular activities are valuable because they:','["are required by every employer", "guarantee a job", "replace all classes", "develop teamwork and show commitment"]'::jsonb,3,'Activities show initiative.','original'),
('127.2.d.3.G',2,'To enroll in a technical program, a student often must:','["complete an application and meet deadlines", "skip the application", "ask a stranger to apply", "wait until the program ends"]'::jsonb,0,'Enrollment requires steps and deadlines.','original'),
('127.2.d.3.G',2,'Admissions steps often include:','["cafeteria receipts", "applications, transcripts and test scores", "yearbook photos", "bus passes"]'::jsonb,1,'These documents support admission.','original'),
('127.2.d.3.H',2,'A professional association for a career pathway offers:','["school grades", "unlimited vacation", "networking, training and industry information", "free groceries"]'::jsonb,2,'Associations support members'' careers.','original'),
('127.2.d.3.H',2,'Which is an example of a professional association?','["a grocery store", "a fan club for a team", "a movie theater chain", "a national trade organization for electricians"]'::jsonb,3,'Trade groups serve a profession.','original'),
('127.2.d.3.I',2,'An entrepreneur is a person who:','["starts and runs a business and takes the financial risk", "inspects school buses", "works only for wages", "collects library books"]'::jsonb,0,'Entrepreneurs create businesses.','original'),
('127.2.d.3.I',2,'Which is an entrepreneurial opportunity?','["reading about lawns only", "starting a lawn-care business", "avoiding all work", "waiting for a job offer only"]'::jsonb,1,'A new business is an entrepreneurial venture.','original'),
('127.2.d.4.A',2,'Which is an effective time-management strategy?','["doing tasks in random order", "skipping the hardest task forever", "making a prioritized to-do list", "waiting until the deadline"]'::jsonb,2,'Lists help organize tasks.','original'),
('127.2.d.4.A',2,'A SMART goal is:','["vague and endless", "impossible to track", "hidden from others", "specific, measurable, achievable, relevant and time-bound"]'::jsonb,3,'SMART describes well-formed goals.','original'),
('127.2.d.4.B',2,'Communication and problem solving are transferable skills because they:','["are useful in many different careers", "apply to one job only", "are only for artists", "expire after school"]'::jsonb,0,'Transferable skills move between jobs.','original'),
('127.2.d.4.B',2,'A student who led a team in a club can use that leadership skill in:','["no job", "many different careers", "only the same school", "only that club"]'::jsonb,1,'Leadership transfers.','original'),
('127.2.d.4.C',2,'A professional presentation includes:','["no preparation", "slang and jokes only", "clear organization, eye contact and appropriate visuals", "reading every word with your back turned"]'::jsonb,2,'Presentations need planning and delivery.','original'),
('127.2.d.4.C',2,'Appropriate technology for a career presentation is:','["slides crowded with paragraphs", "loud music only", "no visuals ever", "slides that support the spoken points"]'::jsonb,3,'Visuals support the speaker.','original'),
('127.2.d.4.D',2,'Using math to calculate a monthly budget is an example of:','["applying core academic skills to personal goals", "a hobby only", "avoiding academics", "guessing"]'::jsonb,0,'Academic skills support life goals.','original'),
('127.2.d.4.D',2,'Writing skills help a student reach career goals by:','["replacing speaking", "making resumes and emails clear", "removing the need to read", "avoiding teamwork"]'::jsonb,1,'Clear writing supports applications and work.','original'),
('127.2.d.4.E',2,'Volunteering in the community benefits a volunteer by:','["ending all studies", "guaranteeing payment", "building skills and connecting with others", "avoiding people"]'::jsonb,2,'Service builds skills and networks.','original'),
('127.2.d.4.E',2,'Community service shows employers that a person is:','["unavailable", "unreliable", "uninterested", "responsible and cares about others"]'::jsonb,3,'Service signals character.','original'),
('127.2.d.4.F',2,'Which characteristic is needed for professional success?','["dependability", "procrastination", "carelessness", "gossip"]'::jsonb,0,'Dependability is valued at work.','original'),
('127.2.d.4.F',2,'Arriving on time and meeting deadlines shows:','["disrespect", "reliability", "laziness", "poor planning"]'::jsonb,1,'Reliable workers meet commitments.','original'),
('127.2.d.5.A',3,'Labor market information shows:','["movie times", "weather patterns", "job growth, wages and demand", "sports scores"]'::jsonb,2,'It describes job trends.','original'),
('127.2.d.5.A',3,'A student researching trends for a career of interest should look at:','["last season''s game scores", "menu prices", "bus routes", "projected job openings over the next decade"]'::jsonb,3,'Projections inform career choices.','original'),
('127.2.d.5.B',3,'A high-demand occupation is one with:','["many job openings compared with available workers", "no openings", "a closing industry", "no workers hired"]'::jsonb,0,'High demand means more jobs than workers.','original'),
('127.2.d.5.B',3,'A high-wage occupation is one that:','["pays below the average", "pays above the average", "has no pay", "pays only in gifts"]'::jsonb,1,'High-wage jobs pay more than typical jobs.','original'),
('127.2.d.5.C',3,'Automation can change employment trends by:','["stopping technology", "ending all work", "reducing some jobs and creating new ones", "raising no demand"]'::jsonb,2,'Technology shifts the job market.','original'),
('127.2.d.5.C',3,'An economic downturn can make hiring:','["impossible forever", "free", "faster in all industries", "slower in many industries"]'::jsonb,3,'Economic conditions affect careers.','original'),
('127.2.d.5.D',3,'A personal budget compares:','["income with expenses", "height with weight", "days with weeks", "grades with attendance"]'::jsonb,0,'A budget balances money in and out.','original'),
('127.2.d.5.D',3,'A student includes rent, car payment and food in her budget. This is planning for:','["a library fine", "her desired lifestyle", "a field trip", "a school dance"]'::jsonb,1,'A budget reflects the lifestyle someone wants.','original'),
('127.2.5.E',3,'To compare salaries of three careers, a student can use:','["a rumor from a friend", "a lottery ticket", "occupational wage data from a government source", "a guess"]'::jsonb,2,'Official wage data is reliable.','original'),
('127.2.5.E',3,'If career A pays $42,000 and career B pays $55,000 per year, career B pays how much more?','["$7,000", "$97,000", "$23,000", "$13,000"]'::jsonb,3,'55,000 minus 42,000 is 13,000.','original'),
('127.2.d.6.A',2,'The first step in an effective job search is often to:','["identify jobs that match skills and interests", "apply to nothing", "quit school", "wait for a call"]'::jsonb,0,'A search begins with matching.','original'),
('127.2.d.6.A',2,'Networking in a job search means:','["ignoring ads", "building contacts who may share job leads", "posting complaints", "avoiding people"]'::jsonb,1,'Contacts can lead to jobs.','original'),
('127.2.6.B',2,'Appropriate interview appearance is:','["a swimsuit", "a costume", "clean, neat and professional clothing", "wrinkled casual clothes"]'::jsonb,2,'Appearance shows respect.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
on conflict (fingerprint) do nothing;
