       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'cte_1_v1'
from (values
('127.2.6.B',2,'For an interview, a candidate''s grooming should be:','["careless", "ignored", "extreme", "neat and appropriate for the workplace"]'::jsonb,3,'Grooming affects first impressions.','original'),
('127.2.d.6.C',2,'In a mock interview, a student practices:','["answering questions and presenting herself professionally", "writing a tax return", "grading papers", "repairing a car"]'::jsonb,0,'Practice builds confidence.','original'),
('127.2.d.6.C',2,'After a mock interview, feedback helps a student:','["memorize every word", "improve answers and confidence", "avoid interviews forever", "skip practice"]'::jsonb,1,'Feedback strengthens performance.','original'),
('127.2.d.7.A',2,'A resume should be:','["ten pages long", "handwritten in code", "accurate, concise and error-free", "full of exaggerations"]'::jsonb,2,'Resumes must be honest and clear.','original'),
('127.2.d.7.A',2,'Which belongs on a resume?','["a home password", "medical details", "a favorite cartoon", "work experience and skills"]'::jsonb,3,'Employers want relevant background.','original'),
('127.2.d.7.B',2,'A cover letter is written to:','["introduce yourself and explain why you fit the job", "apply for a loan", "replace the resume", "list every hobby"]'::jsonb,0,'It connects the applicant to the position.','original'),
('127.2.d.7.B',2,'A thank-you letter after an interview should be sent:','["months later", "soon after the interview", "never", "before the interview"]'::jsonb,1,'Prompt thanks leave a good impression.','original'),
('127.2.d.7.C',2,'When completing a job application, a student should:','["use nicknames only", "guess dates", "give accurate, complete and legible information", "leave sections blank"]'::jsonb,2,'Applications must be accurate.','original'),
('127.2.d.7.C',2,'A sample job application asks for:','["a grocery list", "a social media login", "a password", "contact details, education and work history"]'::jsonb,3,'These are standard application fields.','original'),
('127.2.d.7.C',3,'A plan for starting a career after high school may include:','["education, training, work and financial steps", "only a vacation", "nothing specific", "only a hobby"]'::jsonb,0,'A plan lays out steps to a goal.','original'),
('127.2.d.7.C',3,'A career plan should be reviewed:','["never", "regularly and updated as goals change", "once at age ninety", "only by strangers"]'::jsonb,1,'Plans evolve.','original'),
('127.2.d.7.D',2,'Before listing someone as a reference, a student should:','["use their name secretly", "list a pet", "ask permission", "list a stranger"]'::jsonb,2,'References must agree to serve.','original'),
('127.2.d.7.D',2,'Good references are people who:','["have never met you", "barely know you", "dislike you", "know your work and can speak positively about it"]'::jsonb,3,'References vouch for the applicant.','original'),
('127.2.d.8.A',3,'Military service, entrepreneurship and industry employment are examples of:','["career pathways", "parking zones", "lunch menus", "school holidays"]'::jsonb,0,'They are routes into a career.','original'),
('127.2.d.8.A',3,'A student choosing a pathway should consider:','["only the weather", "interests, skills and training needed", "only the cost of snacks", "only popularity"]'::jsonb,1,'Fit and requirements matter.','original'),
('127.2.d.8.B',3,'Selecting a career pathway begins with:','["picking at random", "waiting for luck", "matching strengths and interests to options", "copying a friend exactly"]'::jsonb,2,'Self-knowledge guides choice.','original'),
('127.2.d.8.B',3,'A student who wants to start a business after school is choosing the pathway of:','["tourism only", "retirement", "recess", "entrepreneurship"]'::jsonb,3,'Starting a business is entrepreneurship.','original'),
('127.13.c.1.A',2,'A carpenter uses math to find the length of a rafter. This is applying mathematics to:','["a workplace problem", "a poem", "a game rule only", "a spelling task"]'::jsonb,0,'Technical work uses math.','original'),
('127.13.c.1.A',2,'A family compares two cell phone plans. This applies math to:','["ancient history only", "everyday life", "a cooking show", "a school mascot"]'::jsonb,1,'Math solves daily problems.','original'),
('127.13.c.1.B',2,'A problem-solving model begins with:','["checking the answer first", "guessing a result", "analyzing the given information", "skipping the plan"]'::jsonb,2,'Analysis comes first.','original'),
('127.13.c.1.B',2,'After formulating a plan, the next step in the model is to:','["restate the title", "erase the data", "stop working", "determine a solution"]'::jsonb,3,'Plan, then solve.','original'),
('127.13.c.1.C',2,'To measure a board precisely, a technician selects:','["a tape measure or ruler", "a stopwatch", "a scale only", "a thermometer"]'::jsonb,0,'Choose a tool that fits the task.','original'),
('127.13.c.1.C',2,'Which tool is best for totaling a long list of costs quickly?','["a level", "a spreadsheet", "a funnel", "a chisel"]'::jsonb,1,'Spreadsheets compute totals.','original'),
('127.13.c.1.D',3,'Explaining a cost estimate with a table and a graph is:','["erasing numbers", "hiding results", "communicating mathematical ideas with multiple representations", "guessing prices"]'::jsonb,2,'Different forms communicate ideas.','original'),
('127.13.c.1.D',3,'A technician shows one relationship as an equation and as a graph. Using several forms helps because:','["it removes all errors", "it avoids communication", "it hides the answer", "different forms clarify different aspects"]'::jsonb,3,'Representations complement each other.','original'),
('127.13.c.1.E',2,'A table that records hours worked and pay earned is a way to:','["organize and record mathematical ideas", "avoid numbers", "hide data", "guess pay"]'::jsonb,0,'Tables organize data.','original'),
('127.13.c.1.E',2,'Drawing a diagram of a room before computing its area is:','["a final answer", "creating a representation", "adding a distraction", "skipping the problem"]'::jsonb,1,'A diagram represents the situation.','original'),
('127.13.c.1.F',3,'Seeing that doubling a side length changes an area helps a worker:','["ignore units", "guess a size", "connect and communicate relationships", "avoid calculating"]'::jsonb,2,'Relationships link ideas.','original'),
('127.13.c.1.F',3,'Analyzing how two quantities change together is studying:','["handwriting", "music", "grammar", "mathematical relationships"]'::jsonb,3,'Relationships describe change.','original'),
('127.13.c.1.G',3,'Justifying a bid means:','["explaining with precise math language why the numbers are correct", "hiding the formula", "copying a rival''s bid", "saying the numbers are secret"]'::jsonb,0,'Justification supports a claim.','original'),
('127.13.c.1.G',3,'Precise mathematical language includes terms like:','["maybe and kinda", "perimeter and coefficient", "whatever and stuff", "thingy and doohickey"]'::jsonb,1,'Exact terms avoid confusion.','original'),
('127.13.c.2.A',3,'A roof rises 6 feet over a run of 12 feet. The rise to run ratio is:','["2 to 1", "6 to 1", "1 to 2", "12 to 6 plus 1"]'::jsonb,2,'6 over 12 simplifies to 1 to 2.','original'),
('127.13.c.2.A',3,'A staircase has a total rise of 42 inches over 6 steps. Each step''s rise is:','["8 inches", "6 inches", "252 inches", "7 inches"]'::jsonb,3,'42 divided by 6 is 7.','original'),
('127.13.c.2.B',3,'A value that grows by the same amount each year is:','["linear", "exponential", "constant decay", "random"]'::jsonb,0,'Equal increases are linear.','original'),
('127.13.c.2.B',3,'A machine loses 20% of its value each year. Its value over time is:','["unchanging", "non-linear (exponential decay)", "constant", "linear growth"]'::jsonb,1,'Percent decreases give exponential decay.','original'),
('127.13.c.2.C',3,'Plan A costs $20 plus $5 per hour. Plan B costs $10 plus $7 per hour. The plans cost the same after how many hours?','["10 hours", "15 hours", "5 hours", "2 hours"]'::jsonb,2,'20 + 5h = 10 + 7h gives h = 5.','original'),
('127.13.c.2.C',3,'A system of equations in a best-deal comparison finds:','["the tax rate", "the weight of a box", "the cheapest item in a store", "where two options cost the same"]'::jsonb,3,'The solution is the break-even point.','original'),
('127.13.c.2.D',4,'Linear programming is used to:','["find the best value of a quantity within limits", "count to ten", "spell technical terms", "draw a floor plan"]'::jsonb,0,'It optimizes under constraints.','original'),
('127.13.c.2.D',4,'In linear programming, constraints are:','["the profit goal", "the limits on resources or conditions", "the graph colors", "the final answer"]'::jsonb,1,'Constraints restrict choices.','original'),
('127.13.c.2.E',3,'In business, 3,000,000 can be written as:','["30 x 10^6", "3 x 10^5", "3 x 10^6", "3 x 10^7"]'::jsonb,2,'Six zeros means 10^6.','original'),
('127.13.c.2.E',3,'The value of 10^3 is:','["100", "10,000", "30", "1,000"]'::jsonb,3,'10 cubed is 1,000.','original'),
('127.13.c.2.F',2,'The square root of 81 is:','["9", "40.5", "8", "18"]'::jsonb,0,'9 times 9 is 81.','original'),
('127.13.c.2.F',2,'What is 2 to the power of 5?','["25", "32", "10", "64"]'::jsonb,1,'2 x 2 x 2 x 2 x 2 = 32.','original'),
('127.13.c.2.G',3,'Compound interest means interest is earned on:','["neither", "only the principal", "the principal and previously earned interest", "only the interest"]'::jsonb,2,'Compounding grows on both.','original'),
('127.13.c.2.G',3,'After two years of 10% interest compounded annually on $1,000, the balance is:','["$1,200", "$1,020", "$1,100", "$1,210"]'::jsonb,3,'1,000 x 1.1 x 1.1 = 1,210.','original'),
('127.13.c.2.H',3,'Depreciation of equipment means:','["its value decreases over time", "its price never changes", "its warranty ends only", "its value increases over time"]'::jsonb,0,'Equipment loses value.','original'),
('127.13.c.2.H',3,'A $10,000 machine loses 10% of its value in one year. Its value is then:','["$1,000", "$9,000", "$9,990", "$10,000"]'::jsonb,1,'10,000 less 1,000 is 9,000.','original'),
('127.13.c.3.A',2,'To find the area of a rectangular floor, a worker needs which formula?','["twice the length", "length plus width", "length times width", "width divided by length"]'::jsonb,2,'Area of a rectangle is length x width.','original'),
('127.13.c.3.A',2,'To find the volume of a cylinder, a technician uses:','["half base times height", "twice the radius", "length times width", "pi times radius squared times height"]'::jsonb,3,'V = pi r squared h.','original'),
('127.13.c.3.B',2,'A rectangular room is 12 feet by 10 feet. Its area is:','["120 square feet", "44 square feet", "22 square feet", "240 square feet"]'::jsonb,0,'12 x 10 = 120.','original'),
('127.13.c.3.B',2,'The perimeter of a 12 ft by 10 ft room is:','["120 feet", "44 feet", "60 feet", "22 feet"]'::jsonb,1,'2(12 + 10) = 44.','original'),
('127.13.c.3.C',3,'In a right triangle, the tangent of an angle equals:','["opposite over hypotenuse", "adjacent over hypotenuse", "opposite over adjacent", "hypotenuse over opposite"]'::jsonb,2,'Tan = opposite/adjacent.','original'),
('127.13.c.3.C',3,'To find the angle a ladder makes with the ground, a worker may use:','["only estimation", "only addition", "only rounding", "sine, cosine or tangent"]'::jsonb,3,'Trig ratios relate sides and angles.','original'),
('127.13.c.3.D',4,'Heron''s formula finds the area of a triangle when:','["all three side lengths are known", "only the height is known", "only the color is known", "only one angle is known"]'::jsonb,0,'It uses the three sides.','original'),
('127.13.c.3.D',4,'For a triangle with sides 3, 4 and 5, the semiperimeter used in Heron''s formula is:','["12", "6", "4", "5"]'::jsonb,1,'(3 + 4 + 5) / 2 = 6.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Career Development' and d.language = 'en'
